const data = await ctx.call("records", {});
const tags = [...new Set(data.records.filter(r => r.active).flatMap(r => String(r.tags ?? "").split(",").map(t => t.trim().toLowerCase()).filter(Boolean)))].sort();
ctx.done({tags});

